(() => {
 const el=id=>document.getElementById(id),labels={portrait:'立繪',sprite:'行走圖',background:'場景'};let artData=null,assetData=null,calendarKey='',cgKey='';
 const option=(s,v,label)=>{const o=document.createElement('option');o.value=v;o.textContent=label;s.append(o);};
 async function art(operation,params={}){const r=await fetch('/api/art',operation?{method:'POST',headers:{'X-Play-Token':token,'Content-Type':'application/json'},body:JSON.stringify({operation,params})}:{headers:{'X-Play-Token':token}});const d=await r.json();if(!r.ok)throw Error(d.message||'素材操作失敗');return d;}
 const actionReport=(id,result)=>report(id,result?.error?.message||result?.notice||'操作已送出',!!(result?.failed||result?.error));
 const report=(id,text,error=false)=>{el(id).textContent=text;el(id).classList.toggle('error',error);};
 function show(id){game.keys.clear();el(id).showModal();}
 for(const b of document.querySelectorAll('[data-life-close]'))b.onclick=()=>el(b.dataset.lifeClose).close();
 for(const id of ['town-modal','illustration-modal','assets-modal'])el(id).addEventListener('close',()=>game.keys.clear());
 function calendar(){const key=JSON.stringify(state.town?.calendar);if(key===calendarKey)return;calendarKey=key;const list=el('town-calendar');list.replaceChildren();for(const row of state.town?.calendar||[]){const card=document.createElement('section');card.className='art-job';const title=document.createElement('h3');title.textContent=`${row.status==='active'?'正在舉行':'即將到來'} · ${row.title}`;const p=document.createElement('p');const hour=((row.start+840)%1440)/60;p.textContent=`DAY ${row.day} · ${Math.floor(hour)}:${String(Math.round(hour%1*60)).padStart(2,'0')} · ${state.location_names[row.venue]}\n${row.description}`;const b=document.createElement('button');b.textContent='走到活動場所';b.onclick=()=>{el('town-modal').close();send('visit',{location:row.venue},true);};card.append(title,p,b);list.append(card);}}
 function people(){for(const id of ['town-speaker','town-target']){const select=el(id),old=select.value;select.replaceChildren();for(const p of state.roster.filter(p=>state.space.entities.some(e=>e.id===p.id))){if(id==='town-speaker'&&p.scripted)continue;option(select,p.id,`${p.name}${p.scripted?' · 一般 NPC':''}`);}if([...select.options].some(o=>o.value===old))select.value=old;}if(el('town-speaker').value===el('town-target').value){const different=[...el('town-target').options].find(o=>o.value!==el('town-speaker').value);if(different)el('town-target').value=different.value;}}
 function pool(){const wrap=el('pool-actions');wrap.replaceChildren();const p=state.town?.pool;if(!p?.here){const b=document.createElement('button');b.textContent='前往晴水游泳池';b.onclick=()=>{el('town-modal').close();send('visit',{location:'pool'},true);};wrap.append(b);return;}
  const text=document.createElement('p');text.textContent=p.swimwear?'已穿泳裝。走到藍色水域後可以游泳。':'下水必須先換泳裝。更衣櫃位於泳池左下方。';const locker=document.createElement('button');locker.textContent='走到更衣櫃';locker.onclick=()=>{el('town-modal').close();send('walk',{x:p.locker?.[0]??5,y:(p.locker?.[1]??15)-1},true);};const change=document.createElement('button');change.textContent='換租借泳裝 · '+(p.rental_price??12)+' 代幣';change.disabled=!p.near_locker||p.swimwear;change.onclick=async()=>{const r=await send('pool_change');actionReport('town-status',r);pool();};const swim=document.createElement('button');swim.textContent='游泳'+(p.swim_minutes??15)+'分鐘';swim.disabled=busy||!!state.facility?.job||!p.swimwear||!p.in_water;swim.onclick=async()=>{const r=await send('pool_swim');actionReport('town-status',r);pool();};wrap.append(text,locker,change,swim);}
 el('town-open').onclick=()=>{if(!state)return;show('town-modal');calendar();people();pool();conversation();const p=state.town.policy;el('town-auto').checked=p.auto_ai;el('town-interval').value=p.interval;el('town-limit').value=p.daily_limit;report('town-status','公告與一般 NPC 的日程不使用聊天 API。');};
 el('town-chat').onclick=async()=>{report('town-status','角色正在各自回應…');const r=await send('town_chat',{speaker:el('town-speaker').value,target:el('town-target').value});actionReport('town-status',r);};
 el('town-policy').onclick=async()=>{const r=await send('town_policy',{auto_ai:el('town-auto').checked,interval:Number(el('town-interval').value),daily_limit:Number(el('town-limit').value)});actionReport('town-status',r);};
 function cgJobs(){const chosen=state.cg.timeline?.auto_show?state.cg.timeline.active:state.cg.selected,jobs=state.cg.jobs.slice(-15),key=JSON.stringify({jobs,chosen});if(key===cgKey)return;cgKey=key;const list=el('illustration-jobs');list.replaceChildren();if(chosen){const f=document.createElement('figure'),im=document.createElement('img'),c=document.createElement('figcaption');im.src=chosen.url;im.alt='目前套用的 SD CG';c.textContent='目前套用的 CG · '+chosen.scene.place_name;f.append(c,im);list.append(f);}for(const j of [...jobs].reverse().filter(j=>j.job_id!==chosen?.job_id)){const figure=document.createElement('figure');const p=document.createElement('figcaption');p.textContent=`${state.roster.find(p=>p.id===j.scene.character)?.name||'你'} · ${j.status} · ${state.location_names[j.scene.scene]||j.scene.scene}`;figure.append(p);if(j.status==='ready'&&j.url){const image=document.createElement('img');image.src=j.url;image.alt='SD 場景插圖';image.loading='lazy';const link=document.createElement('a');link.href=j.url;link.download='cg-'+j.job_id+'.png';link.textContent='下載插圖';figure.append(image,link);}list.append(figure);}}
 el('illustration-open').onclick=()=>{if(!state)return;show('illustration-modal');const select=el('illustration-character');select.replaceChildren();option(select,'player','你 · 成年男性主角');for(const p of state.roster.filter(p=>!p.scripted&&state.space.entities.some(e=>e.id===p.id&&e.near)))option(select,p.id,p.name);if(selected&&[...select.options].some(o=>o.value===selected))select.value=selected;el('illustration-scene').value=state.location_name;cgJobs();report('illustration-status','先在生圖設定綁定所選人物的 LoRA。泳池穿著另需綁定泳裝 LoRA。');};
 el('illustration-generate').onclick=async()=>{const r=await send('cg',{target:el('illustration-character').value,description:el('illustration-description').value});actionReport('illustration-status',r);cgJobs();};
 function assetTargets(){const kind=el('asset-kind').value,s=el('asset-target');s.replaceChildren();if(kind==='background')for(const [id,name] of Object.entries(state.location_names))option(s,id,name);else for(const p of [{id:'player',name:'你 · 男性主角'},...state.roster])option(s,p.id,p.name);assetSize();}
 function assetSize(){const type=el('asset-kind').value,target=el('asset-target').value;el('asset-expression').disabled=type!=='portrait';el('asset-frames').disabled=type!=='sprite';el('asset-outfit').disabled=type==='background';el('asset-hide-decor').disabled=type!=='background';const map=game.spec.maps[target];el('asset-size').textContent=type==='background'&&map?`背景需 ${map.width*32}×${map.height*32} PNG；圖上門口應與原位置對齊。`:type==='sprite'?'行走表：從上到下為背面、向左、正面、向右；64px 一格，PNG 透明背景。':'立繪使用 PNG，可含透明背景。';}
 function installed(){const list=el('asset-installed');list.replaceChildren();for(const [slot,e] of Object.entries(assetData.entries)){const row=document.createElement('p');row.textContent=`${labels[e.kind]} · ${state.location_names[e.target]||state.roster.find(p=>p.id===e.target)?.name||'你'} · ${e.kind==='portrait'?e.expression:''} `;const b=document.createElement('button');b.textContent='恢復原美術';b.onclick=async()=>{try{assetData=await art('asset_remove',{slot});installed();report('asset-status','已恢復原美術；上傳原圖仍保留在本機。');}catch(error){report('asset-status',error.message,true);}};row.append(b);list.append(row);}}
 function library(){const list=el('portrait-library');list.replaceChildren();for(const e of [...artData.portrait_library||[]].reverse()){const figure=document.createElement('figure'),image=document.createElement('img'),caption=document.createElement('figcaption');image.src=e.url;image.alt='可複用立繪差分';image.loading='lazy';caption.textContent=`${state.roster.find(p=>p.id===e.actor)?.name||'你'} · ${artData.expression_labels[e.expression]} · ${e.outfit.title}`;const b=document.createElement('button');b.textContent='套用此差分';b.onclick=async()=>{try{artData=await art('portrait_use',{id:e.id});report('asset-status','已套用立繪差分，沒有再生圖。');}catch(error){report('asset-status',error.message,true);}};figure.append(image,caption,b);list.append(figure);}if(!list.children.length)list.textContent='完成 SD 立繪後，差分會自動累積在這裡。';}
 el('assets-open').onclick=async()=>{if(!state)return;show('assets-modal');try{artData=await art();assetData=await art('asset_state');assetTargets();const expression=el('asset-expression');expression.replaceChildren();for(const [id,name] of Object.entries(artData.expression_labels))option(expression,id,name);installed();library();report('asset-status','只改圖片；不會改角色記憶、碰撞、門口或錢包。');}catch(error){report('asset-status',error.message,true);}};
 el('asset-kind').onchange=assetTargets;el('asset-target').onchange=assetSize;el('asset-frames').onchange=assetSize;
 el('asset-upload').onclick=async()=>{try{const file=el('asset-file').files[0];if(!file||file.size>3*1024*1024)throw Error('選擇 3 MB 以內的 PNG。');const bytes=new Uint8Array(await file.arrayBuffer());let b='';for(let i=0;i<bytes.length;i+=8192)b+=String.fromCharCode(...bytes.subarray(i,i+8192));assetData=await art('asset_upload',{kind:el('asset-kind').value,target:el('asset-target').value,expression:el('asset-expression').value,scope:el('asset-outfit').checked?'outfit':'all',frames:Number(el('asset-frames').value),image:btoa(b),hide_decor:el('asset-hide-decor').checked});installed();report('asset-status','PNG 已套用；下一次畫面更新即可看到。');}catch(error){report('asset-status',error.message,true);}};
 function conversation(){const a=state.space.entities.find(e=>e.id===el('town-speaker').value),b=state.space.entities.find(e=>e.id===el('town-target').value);el('town-chat').disabled=busy||!a||!b||a.id===b.id||!a.near||Math.abs(a.x-b.x)+Math.abs(a.y-b.y)>2;const box=el('town-conversation');box.replaceChildren();for(const e of state.events.filter(e=>e.kind==='city_spoken').slice(-8)){const p=document.createElement('p');p.textContent=(state.roster.find(p=>p.id===e.actor)?.name||'你')+'：'+e.data.text;box.append(p);}}
 el('town-speaker').onchange=conversation;el('town-target').onchange=conversation;
 window.renderLife=()=>{if(el('town-modal').open){calendar();pool();conversation();}if(el('illustration-modal').open)cgJobs();};
})();
